function parseJSON(value) {
  if (typeof value === 'object' && value !== null) return value;
  let text = String(value || '').trim();
  text = text.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
  const first = text.indexOf('{');
  const last = text.lastIndexOf('}');
  if (first >= 0 && last > first) text = text.slice(first, last + 1);
  return JSON.parse(text);
}
function isUuid(v) {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(String(v || ''));
}
const src = $('Code - Extract Copilot Request').first().json;
const raw = $json.output || $json.text || $json.response || $json.message || $json;
let d = {};
try { d = parseJSON(raw); } catch (e) { d = {}; }

const msg = String(src.message || '').toLowerCase();
const page = String(src.current_page || '').toLowerCase();
const pc = src.page_context || {};
const se = src.selected_entity || {};
const anyJobId = pc.job_opening_uuid || pc.id || pc.job_opening_id || se.job_opening_uuid || se.id || se.job_opening_id || null;
const anyAppId = pc.application_id || pc.application?.id || se.application_id || se.id || null;

let action_type = d.action_type || 'answer';
let workflow_key = d.workflow_key || null;
let intent = d.intent || 'answer_question';
let target_page = d.target_page || null;
let route = d.route || null;
let ui_action = d.ui_action || { type: null, payload: {} };
let missing_fields = Array.isArray(d.missing_fields) ? d.missing_fields : [];
let should_refresh_page = Boolean(d.should_refresh_page || false);
let confidence = Number(d.confidence || 0.5);
let reason = d.reason || '';

const editWords = /(change|update|edit|modify|rewrite|regenerate|improve|convert|make|increase|decrease|add|remove|replace|revise|alter|set)/i;
const jobWords = /(job|opening|role|jd|description|experience|salary|responsibilit|qualification|skill|keyword|senior|junior|architect|developer|engineer)/i;
const skillWords = /(weighted skill|extract skill|generate skill|skill approval|scan and publish|publish|scan job|prepare matching skill)/i;
const scoreWords = /(score candidate|scan candidate|match candidate|rank candidate|shortlist|cv analysis|resume analysis|fuzzy|candidate scanning|candidate matching)/i;
const questionWords = /(generate question|screening question|interview question|question set|create question)/i;
const refineQuestionWords = /(refine question|edit question|change question|regenerate question|modify question|rewrite question)/i;
const navWords = /(take me to|go to|navigate|open page|where is|show me page|switch to)/i;
const newJobWords = /(generate job opening|create job opening|new job opening|from requirement|from mandate|jd from requirement)/i;

if ((page.includes('job') || page.includes('catalog')) && editWords.test(msg) && jobWords.test(msg) && anyJobId) {
  action_type = 'call_workflow'; workflow_key = 'regenerate_job_opening'; intent = 'edit_existing_job_opening'; confidence = Math.max(confidence, 0.98); should_refresh_page = true; reason = 'Job catalog edit request with selected job opening context.';
}
if (skillWords.test(msg) && anyJobId) {
  action_type = 'call_workflow'; workflow_key = 'extract_weighted_skills'; intent = 'extract_weighted_skills'; confidence = Math.max(confidence, 0.95); should_refresh_page = true;
}
if (scoreWords.test(msg) && anyJobId) {
  action_type = 'call_workflow'; workflow_key = 'score_candidates'; intent = 'score_candidates'; confidence = Math.max(confidence, 0.94); should_refresh_page = true;
}
if (refineQuestionWords.test(msg) && (pc.question_id || se.question_id || pc.question?.id)) {
  action_type = 'call_workflow'; workflow_key = 'refine_screening_question'; intent = 'refine_screening_question'; confidence = Math.max(confidence, 0.94); should_refresh_page = true;
} else if (questionWords.test(msg) && anyAppId) {
  action_type = 'call_workflow'; workflow_key = 'screening_questions'; intent = 'generate_screening_questions'; confidence = Math.max(confidence, 0.94); should_refresh_page = true;
}
if (newJobWords.test(msg) && (pc.requirement || se.requirement || src.entities?.requirement)) {
  action_type = 'call_workflow'; workflow_key = 'generate_job_openings'; intent = 'generate_job_openings'; confidence = Math.max(confidence, 0.93); should_refresh_page = true;
}
if (navWords.test(msg) && action_type !== 'call_workflow') {
  action_type = 'navigate'; intent = 'navigation_help'; confidence = Math.max(confidence, 0.85);
  if (msg.includes('job catalog') || msg.includes('catalog')) { target_page = 'job_catalog'; route = '/jobs'; }
  else if (msg.includes('sourcing')) { target_page = 'sourcing_pool'; route = '/pool'; }
  else if (msg.includes('stage')) { target_page = 'stages'; route = '/rounds'; }
  else if (msg.includes('client') || msg.includes('mandate')) { target_page = 'clients_mandates'; route = '/clients'; }
  else if (msg.includes('notification') || msg.includes('alert')) { target_page = 'notifications'; route = '/notifications'; }
  else if (msg.includes('setting')) { target_page = 'settings'; route = '/settings'; }
  else if (msg.includes('dashboard')) { target_page = 'dashboard'; route = '/dashboard'; }
}

if (action_type === 'call_workflow' && !workflow_key) {
  action_type = 'clarification';
  missing_fields.push('workflow_key');
}

return [{
  json: {
    ...src,
    action_type,
    intent,
    workflow_key,
    confidence,
    reason,
    target_page,
    route,
    entity_type: d.entity_type || null,
    entity_id: d.entity_id || anyJobId || anyAppId || null,
    missing_fields,
    ui_action,
    recruiter_instruction: d.recruiter_instruction || src.message,
    should_refresh_page,
    router_raw: d,
    has_missing_fields: missing_fields.length > 0
  }
}];

function parseJSON(value){ if(typeof value==='object'&&value!==null)return value; let text=String(value||'').trim().replace(/^```json\s*/i,'').replace(/^```\s*/i,'').replace(/```$/i,'').trim(); const f=text.indexOf('{'); const l=text.lastIndexOf('}'); if(f>=0&&l>f) text=text.slice(f,l+1); return JSON.parse(text); }
const src = $('Code - Build Direct Help Prompt').first().json;
let p = {};
try { p = parseJSON($json.output || $json.text || $json.response || $json.message || $json); } catch(e) { p = {}; }
let message = p.message || '';
if (!message) {
  if (src.action_type === 'navigate') message = `Opening ${src.target_page || 'the requested page'}.`;
  else if ((src.missing_fields || []).length) message = `I need ${src.missing_fields.join(', ')} to continue.`;
  else message = 'I can help with this page. Please share the exact item you want to update or review.';
}
return [{ json: {
  status: 'success',
  request_id: src.request_id,
  automation_type: 'ats_ai_copilot',
  action_type: src.action_type || 'answer',
  intent: src.intent,
  workflow_called: false,
  workflow_key: null,
  message,
  assistant_reply: message,
  navigation: p.navigation || { route: src.route || null, page: src.target_page || null, entity_id: src.entity_id || null, reason: src.reason || null },
  ui_action: p.ui_action || src.ui_action || { type: null, payload: {} },
  data: p.data || {},
  missing_fields: p.missing_fields || src.missing_fields || [],
  should_refresh_page: Boolean(p.should_refresh_page || src.should_refresh_page || false),
  confidence: Number(p.confidence || src.confidence || 0.5),
  completed_at: new Date().toISOString()
}}];

function parseJSON(value){ if(typeof value==='object'&&value!==null)return value; let text=String(value||'').trim().replace(/^```json\s*/i,'').replace(/^```\s*/i,'').replace(/```$/i,'').trim(); const f=text.indexOf('{'); const l=text.lastIndexOf('}'); if(f>=0&&l>f) text=text.slice(f,l+1); return JSON.parse(text); }
function isUuid(v){ return /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(String(v||'')); }
function firstNonEmpty(...vals){ for (const v of vals) { if (v !== undefined && v !== null && String(v).trim() !== '') return v; } return null; }
const src = $('Code - Build Workflow Payload Prompt').first().json;
let agent = {};
try { agent = parseJSON($json.output || $json.text || $json.response || $json.message || $json); } catch(e) { agent = {}; }
const pc = src.page_context || {};
const se = src.selected_entity || {};
const ents = src.entities || {};
const workflowKey = src.workflow_key;
const paths = src.workflow_endpoints || {};
const defaultCallbacks = src.default_callback_urls || {};
const callback = src.callback_url || defaultCallbacks[workflowKey] || null;
const auth = src.authorization || src.auth_header || '';
let payload = agent.payload && typeof agent.payload === 'object' ? agent.payload : {};
let missing = Array.isArray(agent.missing_fields) ? [...agent.missing_fields] : [];
let expected = agent.expected_ui_effect || '';

if (workflowKey === 'regenerate_job_opening') {
  const rawId = firstNonEmpty(pc.job_opening_uuid, se.job_opening_uuid, pc.id, se.id, pc.job_opening_id, se.job_opening_id, src.entity_id);
  const uuid = isUuid(rawId) ? rawId : firstNonEmpty(pc.job_opening_uuid, se.job_opening_uuid, pc.id, se.id);
  const externalId = !isUuid(rawId) ? rawId : firstNonEmpty(pc.job_opening_id, se.job_opening_id);
  payload = {
    automation_type: 'regenerate_job_opening',
    request_id: `regen_${src.request_id}`,
    mode: 'regenerate',
    callback_url: callback,
    authorization: auth,
    auth_header: auth,
    job_opening_uuid: uuid || null,
    job_opening_id: externalId || null,
    instruction: src.recruiter_instruction || src.message,
    recruiter_instruction: src.recruiter_instruction || src.message,
    ai_instruction: { instruction: src.recruiter_instruction || src.message },
    job_details: pc.job_details || pc.job_opening || pc,
    metadata: { copilot_request_id: src.request_id, current_page: src.current_page }
  };
  missing = [];
  if (!payload.job_opening_uuid && !payload.job_opening_id) missing.push('job_opening_uuid or job_opening_id');
  if (!payload.callback_url) missing.push('callback_url');
  expected = 'Regenerate and update the selected job opening.';
}

if (workflowKey === 'extract_weighted_skills') {
  const job = pc.job_opening || se.job_opening || pc;
  payload = {
    automation_type: 'extract_weighted_skills',
    request_id: `skill_${src.request_id}`,
    job_opening_id: firstNonEmpty(job.job_opening_id, job.id, pc.job_opening_id, pc.id, se.job_opening_id, se.id),
    title: job.title || pc.title || se.title || '',
    description: job.description || pc.description || se.description || '',
    responsibilities: job.responsibilities || pc.responsibilities || [],
    qualifications: job.qualifications || pc.qualifications || [],
    keywords: job.keywords || pc.keywords || [],
    salary_range: job.salary_range || pc.salary_range || '',
    callback_url: callback,
    authorization: auth,
    auth_header: auth
  };
  missing=[];
  ['job_opening_id','title','description','callback_url'].forEach(k=>{ if(!payload[k]) missing.push(k); });
  expected = 'Generate weighted skills and store them for recruiter approval.';
}

if (workflowKey === 'score_candidates') {
  const job = pc.job_opening || se.job_opening || {
    job_opening_id: firstNonEmpty(pc.job_opening_id, pc.id, se.job_opening_id, se.id),
    title: pc.title || se.title || '',
    description: pc.description || se.description || '',
    responsibilities: pc.responsibilities || [],
    qualifications: pc.qualifications || [],
    keywords: pc.keywords || []
  };
  const approvedSkills = pc.approved_skills || se.approved_skills || pc.skills || se.skills || ents.approved_skills || [];
  payload = {
    automation_type: 'score_candidates',
    request_id: `score_${src.request_id}`,
    callback_url: callback,
    authorization: auth,
    auth_header: auth,
    job_opening: job,
    approved_skills: approvedSkills,
    match_threshold: Number(pc.match_threshold || src.match_threshold || 60),
    limit: Number(pc.limit || src.limit || 100)
  };
  missing=[];
  if (!payload.callback_url) missing.push('callback_url');
  if (!payload.job_opening || !(payload.job_opening.job_opening_id || payload.job_opening.id)) missing.push('job_opening.job_opening_id');
  if (!Array.isArray(payload.approved_skills) || payload.approved_skills.length === 0) missing.push('approved_skills');
  expected = 'Scan candidate pool, score candidates, and insert shortlisted applications.';
}

if (workflowKey === 'screening_questions') {
  const appId = firstNonEmpty(pc.application_id, pc.application?.id, se.application_id, se.id, src.entity_id);
  payload = {
    automation_type: 'screening_questions',
    request_id: `question_${src.request_id}`,
    mode: 'generate',
    callback_url: callback,
    authorization: auth,
    auth_header: auth,
    application_id: appId,
    recruiter_instruction: src.recruiter_instruction || src.message,
    existing_questions: pc.existing_questions || se.existing_questions || pc.screening_questions || [],
    force_regenerate: Boolean(pc.force_regenerate || /regenerate|again|refresh/i.test(src.message))
  };
  missing=[];
  if (!payload.application_id) missing.push('application_id');
  if (!payload.callback_url) missing.push('callback_url');
  expected = 'Generate candidate-specific screening questions.';
}

if (workflowKey === 'refine_screening_question') {
  const appId = firstNonEmpty(pc.application_id, pc.application?.id, se.application_id, se.application?.id, src.entity_id);
  const qId = firstNonEmpty(pc.question_id, pc.question?.id, se.question_id, se.question?.id);
  payload = {
    automation_type: 'refine_screening_question',
    request_id: `refine_${src.request_id}`,
    mode: 'generate',
    callback_url: callback,
    authorization: auth,
    auth_header: auth,
    application_id: appId,
    question_id: qId,
    instruction: src.recruiter_instruction || src.message,
    refine_prompt: src.recruiter_instruction || src.message,
    refining_prompt: src.recruiter_instruction || src.message,
    prompt: src.recruiter_instruction || src.message,
    existing_questions: pc.existing_questions || pc.screening_questions || [],
    question_details: pc.question || se.question || {}
  };
  missing=[];
  if (!payload.application_id) missing.push('application_id');
  if (!payload.question_id) missing.push('question_id');
  if (!payload.callback_url) missing.push('callback_url');
  expected = 'Refine the selected screening question.';
}

if (workflowKey === 'generate_job_openings') {
  const req = pc.requirement || se.requirement || ents.requirement || src.requirement || {};
  payload = {
    automation_type: 'generate_job_openings',
    request_id: `jobgen_${src.request_id}`,
    callback_url: callback,
    authorization: auth,
    auth_header: auth,
    requirement: req,
    ai_instruction: {
      instruction: src.recruiter_instruction || src.message,
      tone: pc.tone || 'professional',
      output_language: pc.output_language || 'en',
      must_include: pc.must_include || req.skills || [],
      avoid: pc.avoid || ['casual wording']
    },
    metadata: { copilot_request_id: src.request_id }
  };
  missing=[];
  if (!payload.requirement?.requirement_id) missing.push('requirement.requirement_id');
  if (!payload.requirement?.title) missing.push('requirement.title');
  if (!payload.requirement?.description) missing.push('requirement.description');
  if (!payload.requirement?.num_posts_requested) missing.push('requirement.num_posts_requested');
  if (!payload.callback_url) missing.push('callback_url');
  expected = 'Generate one or more job openings from the requirement.';
}

const urlPath = paths[workflowKey] || agent.url_path || null;
return [{
  json: {
    ...src,
    workflow_key: workflowKey,
    method: 'POST',
    url_path: urlPath,
    workflow_url: urlPath ? `${src.n8n_base_url}${urlPath}` : null,
    payload,
    payload_missing_fields: missing,
    workflow_payload_ready: missing.length === 0 && !!urlPath,
    expected_ui_effect: expected,
    should_refresh_page: true,
    payload_architect_raw: agent
  }
}];

const plan = $('Code - Parse Workflow Payload').first().json;
const response = $json;
const prompt = `You are KOZKER Recruiter AI Copilot. A workflow was called. Convert the workflow result into a helpful recruiter-facing chat response and structured frontend response.

Workflow plan:
${JSON.stringify({
  workflow_key: plan.workflow_key,
  expected_ui_effect: plan.expected_ui_effect,
  payload: plan.payload
}, null, 2)}

Workflow HTTP response:
${JSON.stringify(response, null, 2)}

Return ONLY valid JSON:
{
  "message": "short recruiter-facing response",
  "navigation": {"route": null, "page": null, "entity_id": null, "reason": null},
  "ui_action": {"type": "toast", "payload": {"variant": "success", "text": ""}},
  "data": {},
  "should_refresh_page": true,
  "confidence": 0.0
}`;
return [{ json: { ...plan, workflow_http_response: response, final_response_prompt: prompt } }];

function parseJSON(value){ if(typeof value==='object'&&value!==null)return value; let text=String(value||'').trim().replace(/^```json\s*/i,'').replace(/^```\s*/i,'').replace(/```$/i,'').trim(); const f=text.indexOf('{'); const l=text.lastIndexOf('}'); if(f>=0&&l>f) text=text.slice(f,l+1); return JSON.parse(text); }
const plan = $('Code - Build Workflow Result Prompt').first().json;
let p = {};
try { p = parseJSON($json.output || $json.text || $json.response || $json.message || $json); } catch(e) { p = {}; }
const statusCode = plan.workflow_http_response?.statusCode || plan.workflow_http_response?.status || 200;
const ok = Number(statusCode) < 400;
let msg = p.message || (ok ? `${plan.expected_ui_effect || 'Workflow completed.'}` : 'The workflow was called, but it returned an error.');
return [{ json: {
  status: ok ? 'success' : 'failed',
  request_id: plan.request_id,
  automation_type: 'ats_ai_copilot',
  action_type: 'call_workflow',
  intent: plan.intent,
  workflow_called: true,
  workflow_key: plan.workflow_key,
  workflow_url: plan.workflow_url,
  message: msg,
  assistant_reply: msg,
  navigation: p.navigation || { route: null, page: null, entity_id: plan.entity_id || null, reason: null },
  ui_action: p.ui_action || { type: 'toast', payload: { variant: ok ? 'success' : 'error', text: msg } },
  data: p.data || {},
  workflow_response: plan.workflow_http_response,
  missing_fields: [],
  should_refresh_page: p.should_refresh_page !== undefined ? Boolean(p.should_refresh_page) : true,
  confidence: Number(p.confidence || plan.confidence || 0.8),
  completed_at: new Date().toISOString()
}}];

const x = $json;
const fields = x.payload_missing_fields || x.missing_fields || [];
const message = `I cannot run ${x.workflow_key || 'the selected workflow'} yet. Missing: ${fields.join(', ')}.`;
return [{ json: {
  status: 'needs_input',
  request_id: x.request_id,
  automation_type: 'ats_ai_copilot',
  action_type: 'clarification',
  intent: x.intent,
  workflow_called: false,
  workflow_key: x.workflow_key,
  message,
  assistant_reply: message,
  navigation: { route: null, page: x.current_page || null, entity_id: x.entity_id || null, reason: 'Missing workflow payload fields.' },
  ui_action: { type: 'show_missing_fields', payload: { fields } },
  missing_fields: fields,
  should_refresh_page: false,
  confidence: x.confidence || 0.7,
  completed_at: new Date().toISOString()
}}];

const x = $('Code - Extract Copilot Request').first().json;
return [{ json: {
  status: 'validation_error',
  request_id: x.request_id || null,
  automation_type: 'ats_ai_copilot',
  action_type: 'clarification',
  message: 'Please send a non-empty message and session_id/recruiter_id.',
  missing_fields: ['message'],
  received: x
}}];
